#include <iostream>
#include <cstring>
#include <vector>
#include <queue>
#include <algorithm>
using namespace std;

const int INF = 1 << 29;
const int MAXN = 500;

struct Flow {
    struct edge { int a, b, cap, flow; };
    vector<int> g[MAXN];
    vector<edge> e;
    int d[MAXN], ptr[MAXN];

    void add_edge(int a, int b, int cap) {
        edge e1 = {a, b, cap, 0};
        edge e2 = {b, a, 0, 0};
        g[a].push_back((int)e.size());
        e.push_back(e1);
        g[b].push_back((int)e.size());
        e.push_back(e2);
    }

    bool bfs(int nodes) {
        queue<int> q;
        q.push(0);
        memset(d, -1, nodes * sizeof(d[0]));
        d[0] = 0;
        while (!q.empty() && d[nodes - 1] == -1) {
            int v = q.front();
            q.pop();
            for (size_t i = 0; i < g[v].size(); ++i) {
                int id = g[v][i], to = e[id].b;
                if (d[to] == -1 && e[id].flow < e[id].cap) {
                    q.push(to);
                    d[to] = d[v] + 1;
                }
            }
        }
        return d[nodes - 1] != -1;
    }

    int dfs(int v, int flow, int nodes) {
        if (!flow) return 0;
        if (v == nodes - 1) return flow;
        for (; ptr[v] < (int)g[v].size(); ++ptr[v]) {
            int id = g[v][ptr[v]], to = e[id].b;
            if (d[to] != d[v] + 1) continue;
            int pushed = dfs(to, min(flow, e[id].cap - e[id].flow), nodes);
            if (pushed) {
                e[id].flow += pushed;
                e[id ^ 1].flow -= pushed;
                return pushed;
            }
        }
        return 0;
    }

    int max_flow(int nodes) {
        int flow = 0;
        while (bfs(nodes)) {
            memset(ptr, 0, nodes * sizeof(ptr[0]));
            while (int pushed = dfs(0, INF, nodes))
                flow += pushed;
        }
        return flow;
    }
};

int n, t, sx, sy, temp[11][11];
bool m[11][11];

int way(int x1, int y1, int x2, int y2) {
    queue<pair<int, pair<int, int> > > q;
    q.push(make_pair(0, make_pair(x1, y1)));
    int h[11][11];
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            h[i][j] = INF;

    while (!q.empty()) {
        int v = q.front().first;
        int x = q.front().second.first;
        int y = q.front().second.second;
        q.pop();
        h[x][y] = v;

        if (x > 0 && m[x - 1][y] && h[x - 1][y] > v + 1) {
            bool target = (x - 1 == x2 && y == y2);
            int lim = temp[x - 1][y];
            if ((target && lim >= v + 1) || (!target && lim > v + 1))
                q.push(make_pair(v + 1, make_pair(x - 1, y)));
        }
        if (y > 0 && m[x][y - 1] && h[x][y - 1] > v + 1) {
            bool target = (x == x2 && y - 1 == y2);
            int lim = temp[x][y - 1];
            if ((target && lim >= v + 1) || (!target && lim > v + 1))
                q.push(make_pair(v + 1, make_pair(x, y - 1)));
        }
        if (x < n - 1 && m[x + 1][y] && h[x + 1][y] > v + 1) {
            bool target = (x + 1 == x2 && y == y2);
            int lim = temp[x + 1][y];
            if ((target && lim >= v + 1) || (!target && lim > v + 1))
                q.push(make_pair(v + 1, make_pair(x + 1, y)));
        }
        if (y < n - 1 && m[x][y + 1] && h[x][y + 1] > v + 1) {
            bool target = (x == x2 && y + 1 == y2);
            int lim = temp[x][y + 1];
            if ((target && lim >= v + 1) || (!target && lim > v + 1))
                q.push(make_pair(v + 1, make_pair(x, y + 1)));
        }
    }
    return h[x2][y2];
}

int main() {
    Flow flow;
    cin >> n >> t;
    queue<pair<int, pair<int, int> > > q;
    char ch;
    int k = 1;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            cin >> ch;
            temp[i][j] = t;
            if (ch == 'Z') {
                sx = i;
                sy = j;
                m[i][j] = false;
            } else if (ch == 'Y') {
                m[i][j] = false;
            } else {
                m[i][j] = true;
            }
            flow.add_edge(0, k++, (ch == 'Z' || ch == 'Y') ? 0 : ch - '0');
        }
    }

    k = n * n + 1;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            cin >> ch;
            flow.add_edge(k++, n * n * 2 + 1, (ch == 'Z' || ch == 'Y') ? 0 : ch - '0');
        }
    }

    q.push(make_pair(0, make_pair(sx, sy)));
    while (!q.empty()) {
        int v = q.front().first;
        int x = q.front().second.first;
        int y = q.front().second.second;
        q.pop();
        temp[x][y] = v;
        if (x > 0 && v + 1 < temp[x - 1][y] && m[x - 1][y])
            q.push(make_pair(v + 1, make_pair(x - 1, y)));
        if (y > 0 && v + 1 < temp[x][y - 1] && m[x][y - 1])
            q.push(make_pair(v + 1, make_pair(x, y - 1)));
        if (x < n - 1 && v + 1 < temp[x + 1][y] && m[x + 1][y])
            q.push(make_pair(v + 1, make_pair(x + 1, y)));
        if (y < n - 1 && v + 1 < temp[x][y + 1] && m[x][y + 1])
            q.push(make_pair(v + 1, make_pair(x, y + 1)));
    }

    k = 0;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            int k1 = n * n;
            ++k;
            for (int z = 0; z < n; ++z) {
                for (int w = 0; w < n; ++w) {
                    ++k1;
                    if (m[i][j] && m[z][w] && way(i, j, z, w) <= t)
                        flow.add_edge(k, k1, INF);
                }
            }
        }
    }

    cout << flow.max_flow(n * n * 2 + 2);
    return 0;
}
